FROM: `    if (duration_minutes !== undefined) updateData.duration_minutes = duration_minutes ? Number(duration_minutes) : null;`
TO: `    if (duration_minutes !== undefined) updateData.duration_minutes = duration_minutes !== null && duration_minutes !== '' ? Number(duration_minutes) : null;`

